"""Stage 7 · Unit 9 Sequences and functions – v4 lessons (9.1 is the model lesson for the whole course)."""
from maths_notes_v4.kit4 import H, R, I, M, W, Y, ER, X, T, K, L, num, mcq, table, short, explain, grid, expr, tiles, machine


def Lpat(n):
    """L-shaped tile pattern n: a corner tile with an arm of n tiles to the right and n tiles up"""
    return [(0, 3)] + [(k, 3) for k in range(1, n + 1)] + [(0, 3 - k) for k in range(1, n + 1)]


def sq(n):
    return [(c, 3 - r) for c in range(n) for r in range(n)]


